<style>
.ss-ai-widget{--ai-bg:#f4f6fa;--ai-panel:#fff;--ai-border:#e2e6ee;--ai-text:#1b1e27;--ai-muted:#737b8d;--ai-purple:#6d4dff;--ai-cyan:#06a5c4;position:relative;display:flex;width:100%;max-width:980px;height:620px;margin:24px auto;background:var(--ai-panel);border:1px solid var(--ai-border);border-radius:18px;overflow:hidden;box-shadow:0 18px 45px rgba(30,35,55,.12);font-family:Sora,Arial,sans-serif;color:var(--ai-text);z-index:3}.ss-ai-widget *{box-sizing:border-box}.ss-ai-sidebar{width:245px;border-right:1px solid var(--ai-border);background:#fafbfc;display:flex;flex-direction:column}.ss-ai-sidebar-head{padding:14px;border-bottom:1px solid var(--ai-border);display:flex;gap:8px}.ss-ai-sidebar button,.ss-ai-new{border:1px solid var(--ai-border);background:#fff;color:var(--ai-text);border-radius:8px;padding:8px 10px;cursor:pointer;font-size:12px}.ss-ai-new{flex:1;background:linear-gradient(135deg,var(--ai-purple),var(--ai-cyan));border:0;color:#fff;font-weight:700}.ss-ai-sessions{overflow:auto;padding:8px}.ss-ai-session{display:flex;align-items:center;gap:4px;border-radius:8px;margin-bottom:4px}.ss-ai-session.active{background:#eeecff}.ss-ai-session-select{flex:1;border:0;background:transparent;text-align:left;padding:10px;color:var(--ai-text);cursor:pointer;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ss-ai-session-delete{border:0;background:transparent;color:var(--ai-muted);cursor:pointer;padding:7px}.ss-ai-main{min-width:0;flex:1;display:flex;flex-direction:column}.ss-ai-header{padding:16px 18px;display:flex;align-items:center;gap:10px;border-bottom:1px solid var(--ai-border)}.ss-ai-orb{width:32px;height:32px;border-radius:9px;background:conic-gradient(var(--ai-purple),var(--ai-cyan),#e0367f,var(--ai-purple));flex:none}.ss-ai-header h3{font-size:14px;margin:0}.ss-ai-header p{font-size:11px;color:var(--ai-muted);margin:2px 0 0}.ss-ai-status{width:7px;height:7px;border-radius:50%;display:inline-block;background:#35c978;box-shadow:0 0 7px #35c978}.ss-ai-drawer{display:none;margin-left:auto}.ss-ai-chat{flex:1;overflow:auto;padding:18px;display:flex;flex-direction:column;gap:12px;background:radial-gradient(circle at 10% 0,rgba(109,77,255,.04),transparent 35%),var(--ai-panel)}.ss-ai-msg{max-width:84%;padding:11px 14px;border:1px solid var(--ai-border);border-radius:13px;font-size:13px;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere}.ss-ai-msg.user{align-self:flex-end;background:#f1f0ff;border-bottom-right-radius:4px}.ss-ai-msg.ai{align-self:flex-start;border-bottom-left-radius:4px}.ss-ai-msg.error{background:#fff4e5;border-color:#f2c99c;color:#8d5600;animation:ssAiIn .35s ease both}.ss-ai-thinking{align-self:flex-start;max-width:90%;padding:13px 15px;border:1px solid var(--ai-border);border-radius:13px;border-bottom-left-radius:4px;background:linear-gradient(180deg,rgba(109,77,255,.05),transparent)}.ss-ai-thinking-label{font:10px monospace;letter-spacing:1px;color:var(--ai-muted);margin-bottom:7px}.ss-ai-thinking-line{font:13px monospace;color:var(--ai-purple);min-height:18px}.ss-ai-trace{margin-top:8px;padding-top:8px;border-top:1px dashed var(--ai-border);font:11px monospace;color:#38a96d}.ss-ai-input{display:flex;gap:8px;padding:13px;border-top:1px solid var(--ai-border);background:#fafbfc}.ss-ai-input textarea{resize:none;min-height:42px;max-height:110px;flex:1;border:1px solid var(--ai-border);border-radius:9px;padding:11px;font:13px Sora,Arial,sans-serif;outline:0}.ss-ai-input textarea:focus{border-color:var(--ai-purple)}.ss-ai-ask{border:0;border-radius:9px;padding:0 17px;background:linear-gradient(135deg,var(--ai-purple),var(--ai-cyan));color:#fff;font-weight:700;cursor:pointer}.ss-ai-ask:disabled{opacity:.5;cursor:not-allowed}.ss-ai-wave-word{display:inline-block;opacity:0;filter:blur(4px);transform:translateY(5px);animation:ssAiWave .45s cubic-bezier(.2,.8,.2,1) forwards;margin-right:4px}@keyframes ssAiWave{to{opacity:1;filter:blur(0);transform:translateY(0)}}@keyframes ssAiIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}@media(max-width:700px){.ss-ai-widget{height:calc(100vh - 30px);min-height:500px;margin:15px 0;border-radius:12px}.ss-ai-sidebar{position:absolute;inset:0 auto 0 0;width:265px;z-index:5;transform:translateX(-102%);transition:transform .2s ease;box-shadow:10px 0 25px rgba(0,0,0,.12)}.ss-ai-widget.drawer-open .ss-ai-sidebar{transform:translateX(0)}.ss-ai-drawer{display:block;border:0;background:transparent;font-size:20px;color:var(--ai-text);cursor:pointer}.ss-ai-msg{max-width:92%}}
/* Floating dashboard placement. The widget remains fixed while the dashboard scrolls. */
.ss-ai-widget{position:fixed !important;right:24px;bottom:24px;margin:0;width:760px;max-width:calc(100vw - 48px);z-index:99999}
@media(max-width:700px){.ss-ai-widget{inset:15px;right:15px;bottom:15px;width:auto;max-width:none;height:auto;min-height:0}}
.ss-ai-launcher{position:fixed;right:24px;bottom:24px;width:58px;height:58px;border:0;border-radius:50%;background:linear-gradient(135deg,#6d4dff,#06a5c4);color:#fff;box-shadow:0 12px 28px rgba(46,55,100,.3),0 0 0 5px rgba(255,255,255,.8);cursor:pointer;z-index:99998;display:flex;align-items:center;justify-content:center;transition:transform .18s ease,box-shadow .18s ease}.ss-ai-launcher:hover{transform:translateY(-3px);box-shadow:0 16px 32px rgba(46,55,100,.38),0 0 0 5px rgba(255,255,255,.9)}.ss-ai-launcher-icon{font-size:27px;line-height:1;font-weight:700}.ss-ai-widget{display:none;right:24px;bottom:24px;width:760px;height:620px}.ss-ai-widget.open{display:flex}.ss-ai-widget .ss-ai-header{background:linear-gradient(135deg,#fbfbff,#f2f8ff);padding:14px 16px}.ss-ai-widget .ss-ai-orb{box-shadow:0 5px 13px rgba(109,77,255,.2)}.ss-ai-close-widget{margin-left:auto;width:32px;height:32px;border:1px solid #e2e6ee;border-radius:9px;background:#fff;color:#687184;font-size:18px;line-height:1;cursor:pointer}.ss-ai-close-widget:hover{background:#f4f6fa;color:#1b1e27}.ss-ai-widget .ss-ai-input{background:#fff;padding:12px 14px}.ss-ai-widget .ss-ai-input textarea{background:#fbfcff;min-height:46px}.ss-ai-widget .ss-ai-ask{min-width:66px}.ss-ai-widget .ss-ai-sidebar{background:#fbfcfe}.ss-ai-widget .ss-ai-chat{background:linear-gradient(180deg,#fff,#fbfcff)}
@media(max-width:700px){.ss-ai-launcher{right:16px;bottom:16px;width:54px;height:54px}.ss-ai-widget{inset:10px;right:10px;bottom:10px;width:auto;height:auto;border-radius:16px}.ss-ai-widget .ss-ai-sidebar{width:280px}}
.ss-ai-textarea-wrap{flex:1;min-width:0;display:flex;flex-direction:column}.ss-ai-word-counter{font-size:10px;color:#737b8d;text-align:right;padding:4px 3px 0}.ss-ai-word-counter.limit{color:#c44b4b;font-weight:700}
</style>
<button class="ss-ai-launcher" id="ssAiLauncher" type="button" aria-label="Open School AI Assistant" title="Open School AI Assistant"><span class="ss-ai-launcher-icon">✦</span></button>
<div class="ss-ai-widget" id="ssAiWidget" aria-hidden="true">
  <aside class="ss-ai-sidebar" aria-label="Chat history">
    <div class="ss-ai-sidebar-head"><button class="ss-ai-new" type="button">+ New chat</button><button class="ss-ai-close" type="button" aria-label="Close history">×</button></div>
    <div class="ss-ai-sessions"></div>
  </aside>
  <section class="ss-ai-main">
    <header class="ss-ai-header"><button class="ss-ai-drawer" type="button" aria-label="Open history">☰</button><span class="ss-ai-orb"></span><div><h3>School AI Assistant</h3><p><span class="ss-ai-status"></span> Connected · Groq</p></div><button class="ss-ai-close-widget" id="ssAiCloseWidget" type="button" aria-label="Close School AI Assistant">×</button></header>
    <div class="ss-ai-chat" aria-live="polite"><div class="ss-ai-msg ai">Hi! Ask me about attendance, student records, fees, or reports.</div></div>
    <form class="ss-ai-input"><div class="ss-ai-textarea-wrap"><textarea maxlength="500" placeholder="Ask about school data…"></textarea><div class="ss-ai-word-counter">0 / 80 words</div></div><button class="ss-ai-ask" type="submit">Ask</button></form>
  </section>
</div>
<script>
(function(){
  var root=document.getElementById('ssAiWidget');
  if(!root){console.error('[AI Widget] Root element #ssAiWidget was not found.');return;}
  console.info('[AI Widget] mounted', {baseUrl:window.base_url||'<?php echo rtrim(base_url(), '/').'/'; ?>',display:getComputedStyle(root).display,position:getComputedStyle(root).position,visibility:getComputedStyle(root).visibility,width:root.offsetWidth,height:root.offsetHeight});
  var launcher=document.getElementById('ssAiLauncher'), closeWidget=document.getElementById('ssAiCloseWidget');
  function openWidget(){root.classList.add('open');root.setAttribute('aria-hidden','false');if(launcher)launcher.style.display='none';}
  function closeWidgetPanel(){root.classList.remove('open');root.setAttribute('aria-hidden','true');if(launcher)launcher.style.display='flex';root.classList.remove('drawer-open');}
  if(launcher)launcher.onclick=openWidget;
  if(closeWidget)closeWidget.onclick=closeWidgetPanel;
  var chat=root.querySelector('.ss-ai-chat'), input=root.querySelector('textarea'), ask=root.querySelector('.ss-ai-ask'), counter=root.querySelector('.ss-ai-word-counter'), list=root.querySelector('.ss-ai-sessions'), current=localStorage.getItem('ss_ai_widget_session_id')||'', maxWords=80;
  function wordCount(value){var t=(value||'').trim();return t?t.split(/\s+/).length:0} function updateWordCounter(){var n=wordCount(input.value);counter.textContent=n+' / '+maxWords+' words';counter.classList.toggle('limit',n>=maxWords);ask.disabled=n>maxWords} input.addEventListener('input',updateWordCounter);updateWordCounter();
  var phrases=['Understanding your request…','Checking permissions…','Reading approved records…','Filtering the result…','Formatting the answer…'], errorCopy={RATE_LIMIT:'You are asking a lot of questions. Please wait a few minutes before trying again.',SESSION_EXPIRED:'This chat has expired and is no longer available. Starting a new one for you…',NETWORK_ERROR:'Having trouble connecting right now. Please check your internet and try again.',AUTH_REQUIRED:'Your session has ended. Please log in again.',INVALID_INPUT:'Please type a question first.',SERVER_ERROR:'Something went wrong on our end. Please try again in a moment.',UNKNOWN_ERROR:'Something went wrong. Please try again.'};
  function url(path){return (window.base_url||'<?php echo rtrim(base_url(), '/').'/'; ?>')+path}
  function bubble(text,kind){var d=document.createElement('div');d.className='ss-ai-msg '+kind;d.textContent=text;chat.appendChild(d);chat.scrollTop=chat.scrollHeight;return d}
  function renderReply(text){var d=bubble('', 'ai');text.split(/\s+/).forEach(function(w,i){var s=document.createElement('span');s.className='ss-ai-wave-word';s.textContent=w;s.style.animationDelay=(i*.035)+'s';d.appendChild(s)});}
  function error(code,retry){var d=bubble(errorCopy[code]||errorCopy.UNKNOWN_ERROR,'error');if(retry){var b=document.createElement('button');b.type='button';b.textContent='Retry';b.style.cssText='display:block;margin-top:8px;border:1px solid #e3bd8a;background:#fff7ec;border-radius:7px;padding:5px 10px;color:#875000;cursor:pointer';b.onclick=function(){d.remove();askQuestion(last)};d.appendChild(b)}}
  function thinking(){var d=document.createElement('div');d.className='ss-ai-thinking';d.innerHTML='<div class="ss-ai-thinking-label">● THINKING</div><div class="ss-ai-thinking-line"></div><div class="ss-ai-trace"></div>';chat.appendChild(d);var line=d.querySelector('.ss-ai-thinking-line'),i=0;line.textContent=phrases[0];var timer=setInterval(function(){i=(i+1)%phrases.length;line.textContent=phrases[i]},550);return {node:d,stop:function(){clearInterval(timer);d.remove()}}}
  function post(path,payload){return fetch(url(path),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),credentials:'same-origin'}).then(function(r){return r.text().then(function(t){var j;try{j=JSON.parse(t)}catch(e){j={error:true,error_code:(r.status===401||r.status===403)?'AUTH_REQUIRED':'SERVER_ERROR'}}j.http_status=r.status;return j})})}
  function loadSessions(){fetch(url('ai_widget/sessions'),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){if(!j.error){list.innerHTML='';j.sessions.forEach(function(s){var row=document.createElement('div');row.className='ss-ai-session '+(s.session_id===current?'active':'');var b=document.createElement('button');b.className='ss-ai-session-select';b.type='button';b.textContent=s.title||'New chat';b.onclick=function(){loadHistory(s.session_id)};var x=document.createElement('button');x.className='ss-ai-session-delete';x.type='button';x.textContent='×';x.onclick=function(e){e.stopPropagation();post('ai_widget/delete_session/'+encodeURIComponent(s.session_id),{}).then(loadSessions)};row.appendChild(b);row.appendChild(x);list.appendChild(row)})}}).catch(function(){})}
  function loadHistory(id){fetch(url('ai_widget/history/'+encodeURIComponent(id)),{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(j){if(j.error){localStorage.removeItem('ss_ai_widget_session_id');current='';error('SESSION_EXPIRED');return}current=id;localStorage.setItem('ss_ai_widget_session_id',id);chat.innerHTML='';j.messages.forEach(function(m){bubble(m.content,m.role==='user'?'user':'ai')});root.classList.remove('drawer-open');loadSessions()}).catch(function(){error('NETWORK_ERROR')})}
  function newChat(){post('ai_widget/new_session',{}).then(function(j){if(j.error){error(j.error_code);return}current=j.session_id;localStorage.setItem('ss_ai_widget_session_id',current);chat.innerHTML='';bubble('New chat started. How can I help?','ai');root.classList.remove('drawer-open');loadSessions()}).catch(function(){error('NETWORK_ERROR')})}
  var last=''; function askQuestion(q){q=(q||'').trim();if(!q||wordCount(q)>maxWords){error('INVALID_INPUT');return}last=q;input.value='';updateWordCounter();bubble(q,'user');ask.disabled=true;var t=thinking();post('ai_widget/ask',{session_id:current,message:q}).then(function(j){t.stop();if(j.error){if(j.error_code==='SESSION_EXPIRED'){localStorage.removeItem('ss_ai_widget_session_id');current='';newChat()}else error(j.error_code,j.error_code==='SERVER_ERROR'||j.error_code==='NETWORK_ERROR');return}current=j.session_id;localStorage.setItem('ss_ai_widget_session_id',current);renderReply(j.reply);if(j.tool_used){var tr=bubble('Data source: '+j.tool_used,'ai');tr.style.cssText='font:10px monospace;color:#737b8d;padding:5px 10px;border:0;background:transparent';}loadSessions()}).catch(function(){t.stop();error('NETWORK_ERROR',true)}).finally(function(){updateWordCounter()})}
  var aiForm=root.querySelector('.ss-ai-input');aiForm.onsubmit=function(e){e.preventDefault();if(!input.value.trim())return;askQuestion(input.value)};root.querySelector('.ss-ai-new').onclick=newChat;root.querySelector('.ss-ai-drawer').onclick=function(){root.classList.add('drawer-open')};root.querySelector('.ss-ai-close').onclick=function(){root.classList.remove('drawer-open')};loadSessions();
})();
</script>
